<script setup>
const props=defineProps({indexUrl:String,payload:String});function parse(value){try{return JSON.parse(value||'{}')}catch{return {}}}const data=parse(props.payload),u=data.user||{};function fmt(v){if(!v)return '—';return new Date(v).toLocaleString()}
</script>
<template><div class="dashboard-section users-page users-show-page"><div class="users-edit-hero users-show-hero mb-4"><div class="users-edit-hero-content"><div class="users-edit-breadcrumb"><a :href="indexUrl"><i class="bi bi-people"></i> Users</a><i class="bi bi-chevron-right"></i><span>User Details</span></div><span class="hero-badge"><i class="bi bi-person-vcard"></i> Account Overview</span><h1>{{u.name||[u.first_name,u.last_name].filter(Boolean).join(' ')||u.username}}</h1><p>View profile information, account activity and marketplace details.</p></div><div class="users-edit-hero-mark"><i class="bi bi-person-vcard"></i></div></div><div class="dashboard-panel users-show-profile mb-4"><div class="users-show-profile-main"><div class="users-show-avatar-wrap"><img v-if="data.photo_url" :src="data.photo_url" :alt="u.name" class="users-show-avatar"><div v-else class="users-show-avatar users-show-avatar-initial">{{(u.name||'?').slice(0,1).toUpperCase()}}</div></div><div class="users-show-profile-info"><div class="users-show-name-row"><h2>{{u.name}}</h2><span class="role-pill" :class="u.role==='admin'?'role-admin':'role-member'"><i class="bi bi-person"></i>{{data.role_name}}</span></div><span class="users-show-username">@{{u.username}}</span><span class="users-show-email"><i class="bi bi-envelope"></i>{{u.email}}</span></div><div class="users-show-profile-status"><span class="users-show-status-label">Account status</span><span class="status-pill" :class="'status-'+u.status">{{u.status}}</span></div></div><div class="users-show-quick-stats"><div class="users-show-quick-stat"><div class="users-show-quick-icon"><i class="bi bi-bag-check"></i></div><div><span>Orders</span><strong>{{data.order_count||0}}</strong></div></div><div class="users-show-quick-stat"><div class="users-show-quick-icon"><i class="bi bi-currency-dollar"></i></div><div><span>Total spent</span><strong>{{Number(data.order_total||0).toFixed(2)}}</strong></div></div><div class="users-show-quick-stat"><div class="users-show-quick-icon"><i class="bi bi-calendar-check"></i></div><div><span>Joined</span><strong>{{fmt(u.created_at)}}</strong></div></div><div class="users-show-quick-stat"><div class="users-show-quick-icon"><i class="bi bi-envelope-check"></i></div><div><span>Email</span><strong>{{u.email_verified_at?'Verified':'Unverified'}}</strong></div></div></div></div><div class="row g-4"><div class="col-12 col-xl-8"><section class="dashboard-panel users-show-panel p-4"><h5>Personal information</h5><div class="users-show-info-grid"><div class="users-show-info-item"><span>First name</span><strong>{{u.first_name||'—'}}</strong></div><div class="users-show-info-item"><span>Last name</span><strong>{{u.last_name||'—'}}</strong></div><div class="users-show-info-item"><span>Username</span><strong>@{{u.username}}</strong></div><div class="users-show-info-item"><span>Email</span><strong>{{u.email}}</strong></div><div class="users-show-info-item"><span>Phone</span><strong>{{u.phone||'—'}}</strong></div><div class="users-show-info-item"><span>Registered</span><strong>{{fmt(u.created_at)}}</strong></div></div><h5 class="mt-4">Marketplace activity</h5><div class="users-show-activity-grid"><div class="users-show-activity-card"><span>Total orders</span><strong>{{data.order_count||0}}</strong></div><div class="users-show-activity-card"><span>Total order value</span><strong>{{Number(data.order_total||0).toFixed(2)}}</strong></div></div></section></div><div class="col-12 col-xl-4"><section class="dashboard-panel users-show-side-panel p-4"><h5>Account summary</h5><p>Account ID <strong>#{{u.id}}</strong></p><p>Role <strong>{{data.role_name}}</strong></p><p>Status <strong>{{u.status}}</strong></p><p>Email verification <strong>{{u.email_verified_at?'Verified':'Unverified'}}</strong></p><a :href="u.edit_url||data.edit_url" class="users-show-edit-btn"><i class="bi bi-pencil"></i> Edit user</a><a :href="indexUrl" class="users-show-back-btn mt-2"><i class="bi bi-arrow-left"></i> Back to users</a></section></div></div></div></template>
